#!/usr/bin/env node
// Regenerates examples-bundle.js from the example programs in this folder:
//   node docs/lab/examples/build-bundle.js
// The lab page loads the bundle so it needs no fetch; the .js files next to it are the source of truth.
const fs = require('fs'), path = require('path');
const here = __dirname;
const META = [
  { id: 'measure', title: 'Measure', words: ['measure', 'distance', 'how far', 'far'], reply: 'Measuring from there. Look at the second point and hold still, or say "set".' },
  { id: 'surfaces', title: 'Surfaces', words: ['surface', 'surfaces', 'found', 'scan', 'planes'], reply: 'Outlining each surface as the device finds it.' },
  { id: 'keep-clear', title: 'Keep-clear zone', words: ['keep clear', 'keep-clear', 'safety', 'zone', 'circle', 'exclusion'], reply: 'Two metre zone on the floor in front of it.' },
  { id: 'route', title: 'Route', words: ['route', 'guide', 'way', 'take me', 'navigate', 'path'], reply: 'Follow the trail.' },
  { id: 'height', title: 'Height', words: ['height', 'high', 'tall'], reply: 'Measured from the floor.' },
];
const examples = META.map(m => {
  const code = fs.readFileSync(path.join(here, m.id + '.js'), 'utf8');
  const prompt = (code.match(/^\/\/ "(.+)"/) || [null, m.title])[1];
  return { ...m, prompt, code };
});
const out = '// Generated by build-bundle.js from the example programs in this folder. Do not edit by hand.\n' +
  'window.SPATAIL_LAB_EXAMPLES = ' + JSON.stringify(examples) + ';\n';
fs.writeFileSync(path.join(here, 'examples-bundle.js'), out);
console.log('wrote examples-bundle.js with ' + examples.length + ' examples');
